import {contact} from './ladder.mjs';
import {dualOutputLogic} from './dual-model.mjs';
const path=(d,on)=>`<path class="wire ${on?'on':''}" d="${d}"/>`;
const coil=(tag,value)=>`<g class="coil ${value?'on':''}"><text x="356" y="15">${tag}</text><path d="M344 25Q326 40 344 55M368 25Q386 40 368 55"/><text x="356" y="44">${Number(value)}</text></g>`;
export function runSVG(s){const c=s.control||{startOK:false,previous:s.run,stop:false,fault:s.fault},joined=c.startOK||c.previous,afterStop=joined&&!c.stop,blocked=c.fault||c.done;return `<svg viewBox="0 0 420 135" role="img" aria-label="Memoria de marcha RUN igual a ${Number(s.run)}">${path('M15 18V119M15 40H35V100',true)}${path('M35 40H74',true)}${contact({tag:'START_OK',pass:c.startOK},80,40)}${path('M86 40H143',c.startOK)}${path('M35 100H74',true)}${contact({tag:'RUN previo',pass:c.previous},80,100)}${path('M86 100H143V40',c.previous)}${path('M143 40H189',joined)}${contact({tag:'PARO',pass:!c.stop,nc:true},195,40)}${path('M201 40H269',afterStop)}${contact({tag:'BLOQUEO',pass:!blocked,nc:true},275,40)}${path('M281 40H337',afterStop&&!blocked)}${coil('RUN',s.run)}${path('M375 40H405V119',s.run)}</svg>`;}
export function controlledOutputSVG(s,key,tag){const l=dualOutputLogic(s,key),a=l.gate&&l.auto&&l.stage,b=l.gate&&l.manual&&l.request,v=a||b;return `<svg viewBox="0 0 420 135" role="img" aria-label="${tag} igual a ${Number(v)}">${path('M15 18V119M15 40H44',true)}${contact({tag:'RUN válido',pass:l.gate},50,40)}${path('M56 40H90V100',l.gate)}${path('M90 40H139',l.gate)}${contact({tag:'AUTO',pass:l.auto},145,40)}${path('M151 40H239',l.gate&&l.auto)}${contact({tag:key==='q'?'A+/B+/B−':'B+',pass:l.stage},245,40)}${path('M251 40H310',a)}${path('M90 100H139',l.gate)}${contact({tag:'MAN',pass:l.manual},145,100)}${path('M151 100H239',l.gate&&l.manual)}${contact({tag:key==='q'?'MA':'MB',pass:l.request},245,100)}${path('M251 100H310V40',b)}${path('M310 40H337',v)}${coil(tag,v)}${path('M375 40H405V119',v)}</svg>`;}
export function operatorPanel(panel,onCommand){const div=document.createElement('section');div.className='operator-panel';div.setAttribute('aria-label','Pupitre de mando');div.innerHTML=`<span class="eyebrow">PUPITRE DE MANDO</span><div class="operator-modes" role="group" aria-label="Modo"><button data-command="auto">Automático</button><button data-command="manual">Manual</button></div><div class="operator-actions"><button data-command="start" class="start-button">● Marcha</button><button data-command="stop" class="stop-button">■ Paro</button><strong id="runStatus"></strong></div><div class="manual-controls" role="group" aria-label="Órdenes manuales"><button data-command="A+">A+ · extender</button><button data-command="A−">A− · retornar</button><button data-command="B+">B+ · extender</button><button data-command="B−">B− · retornar</button></div><p id="operatorMessage" role="status"></p><p>Paro quita las salidas: con aire y sin atasco, ambos cilindros retornan. Pausar simulación congela el tiempo. En manual, las órdenes quedan retenidas; no siguen la secuencia automática.</p></section>`;panel.querySelector('.ladder-actions').before(div);div.addEventListener('click',e=>{const b=e.target.closest('[data-command]');if(b)onCommand(b.dataset.command)});return (s,disabled)=>{for(const mode of ['auto','manual']){const b=div.querySelector(`[data-command="${mode}"]`);b.setAttribute('aria-pressed',String(s.mode===mode));b.disabled=disabled;}div.querySelector('[data-command="stop"]').disabled=disabled;div.querySelector('[data-command="start"]').disabled=s.run||s.fault||(s.mode==='auto'&&s.complete)||disabled;for(const cmd of ['A+','A−','B+','B−']){const b=div.querySelector(`[data-command="${cmd}"]`);b.disabled=disabled||s.mode!=='manual'||!s.run||s.fault;b.setAttribute('aria-pressed',String(!b.disabled&&((cmd[0]==='A'?s.manualA:s.manualB)===(cmd[1]==='+'))));}div.querySelector('#runStatus').textContent=s.run?'RUN · 1':'RUN · 0';const msg=div.querySelector('#operatorMessage');if(msg.textContent!==s.operatorMessage)msg.textContent=s.operatorMessage;};}
